<?php
namespace App\Http\Controllers;
use App\Services\DocumentIntegrationService;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Support\Facades\Storage;
class ServiceRequestController extends Controller{
private function staff(Request $r){$u=$r->user();return $u->isSuperAdmin()||$u->hasRole('admin')||$u->hasRole('request_dispatcher')||$u->canDo('requests.view')||$u->canDo('requests.manage');}
private function canSee(Request $r,$x){return $this->staff($r)||$x->created_by===$r->user()->id||$x->assigned_to===$r->user()->id;}
private function number(){return DB::transaction(function(){$y=(int)date('Y');$row=DB::table('service_request_sequences')->where('year',$y)->lockForUpdate()->first();if(!$row){DB::table('service_request_sequences')->insert(['year'=>$y,'last_number'=>1]);$n=1;}else{$n=$row->last_number+1;DB::table('service_request_sequences')->where('year',$y)->update(['last_number'=>$n]);}return 'ЗАЯВ-'.$y.'-'.str_pad($n,5,'0',STR_PAD_LEFT);});}
public function index(Request $r){$q=DB::table('service_requests as x')->join('request_categories as c','c.id','=','x.request_category_id')->leftJoin('users as u','u.id','=','x.assigned_to')->select('x.*','c.name as category_name','c.department','u.name as assignee_name');if(!$this->staff($r))$q->where('x.created_by',$r->user()->id);if($r->filled('status'))$q->where('x.status',$r->status);if($r->filled('q')){$s='%'.$r->q.'%';$q->where(fn($z)=>$z->where('x.number','like',$s)->orWhere('x.title','like',$s));}$rows=$q->orderByRaw("CASE WHEN x.status IN ('resolved','closed','cancelled') THEN 1 ELSE 0 END")->orderBy('x.due_at')->get();$stats=['new'=>DB::table('service_requests')->where('status','new')->count(),'work'=>DB::table('service_requests')->whereIn('status',['assigned','in_progress','waiting'])->count(),'overdue'=>DB::table('service_requests')->whereNotIn('status',['resolved','closed','cancelled'])->where('due_at','<',now())->count(),'resolved'=>DB::table('service_requests')->where('status','resolved')->count()];return view('requests.index',compact('rows','stats'));}
public function create(Request $r){$cats=DB::table('request_categories')->where('active',1)->when($r->user()->student_id,fn($q)=>$q->where('allow_students',1))->orderBy('department')->get();return view('requests.create',compact('cats'));}
public function store(Request $r){$d=$r->validate(['request_category_id'=>'required|exists:request_categories,id','title'=>'required|string|max:500','description'=>'required|string|max:20000','priority'=>'required|in:low,normal,high,urgent','official_appeal'=>'nullable|boolean','files.*'=>'nullable|file|max:10240']);$cat=DB::table('request_categories')->find($d['request_category_id']);abort_if(!$cat||($r->user()->student_id&&!$cat->allow_students),403);$id=DB::transaction(function()use($r,$d,$cat){$id=DB::table('service_requests')->insertGetId(['number'=>$this->number(),'request_category_id'=>$cat->id,'created_by'=>$r->user()->id,'student_id'=>$r->user()->student_id,'title'=>$d['title'],'description'=>$d['description'],'priority'=>$d['priority'],'status'=>$cat->default_assignee_id?'assigned':'new','assigned_to'=>$cat->default_assignee_id,'due_at'=>now()->addHours($cat->sla_hours),'official_appeal'=>(bool)($d['official_appeal']??false),'created_at'=>now(),'updated_at'=>now()]);DB::table('service_request_events')->insert(['service_request_id'=>$id,'user_id'=>$r->user()->id,'event'=>'created','created_at'=>now(),'updated_at'=>now()]);return $id;});foreach($r->file('files',[]) as $f){$path=$f->store('service-requests/'.$id,'local');DB::table('service_request_files')->insert(['service_request_id'=>$id,'original_name'=>$f->getClientOriginalName(),'path'=>$path,'mime'=>$f->getMimeType(),'size'=>$f->getSize(),'uploaded_by'=>$r->user()->id,'created_at'=>now(),'updated_at'=>now()]);}return redirect()->route('requests.show',$id);}
public function show(Request $r,$id){$x=DB::table('service_requests as x')->join('request_categories as c','c.id','=','x.request_category_id')->leftJoin('users as u','u.id','=','x.assigned_to')->where('x.id',$id)->select('x.*','c.name as category_name','c.department','u.name as assignee_name')->first();abort_if(!$x,404);abort_unless($this->canSee($r,$x),403);$messages=DB::table('service_request_messages as m')->join('users as u','u.id','=','m.user_id')->where('m.service_request_id',$id)->when(!$this->staff($r),fn($q)=>$q->where('m.internal',0))->select('m.*','u.name as user_name')->orderBy('m.id')->get();$files=DB::table('service_request_files')->where('service_request_id',$id)->get();$events=DB::table('service_request_events')->where('service_request_id',$id)->orderByDesc('id')->get();$users=$this->staff($r)?DB::table('users')->orderBy('name')->get():collect();return view('requests.show',compact('x','messages','files','events','users'));}
public function message(Request $r,$id){$x=DB::table('service_requests')->find($id);abort_if(!$x,404);abort_unless($this->canSee($r,$x),403);$d=$r->validate(['message'=>'required|string|max:20000','internal'=>'nullable|boolean']);$internal=$this->staff($r)&&(bool)($d['internal']??false);DB::transaction(function()use($id,$r,$d,$internal,$x){DB::table('service_request_messages')->insert(['service_request_id'=>$id,'user_id'=>$r->user()->id,'message'=>$d['message'],'internal'=>$internal,'created_at'=>now(),'updated_at'=>now()]);$up=['updated_at'=>now()];if(!$x->first_response_at&&$this->staff($r)&&$x->created_by!==$r->user()->id)$up['first_response_at']=now();if($x->status==='new'&&$this->staff($r))$up['status']='in_progress';DB::table('service_requests')->where('id',$id)->update($up);});return back();}
public function update(Request $r,$id){abort_unless($this->staff($r),403);$x=DB::table('service_requests')->find($id);abort_if(!$x,404);$d=$r->validate(['status'=>'required|in:new,assigned,in_progress,waiting,resolved,closed,cancelled','assigned_to'=>'nullable|exists:users,id','priority'=>'required|in:low,normal,high,urgent','resolution'=>'nullable|string|max:20000']);$up=$d+['updated_at'=>now()];if($d['status']==='resolved'&&!$x->resolved_at)$up['resolved_at']=now();if($d['status']==='closed'&&!$x->closed_at)$up['closed_at']=now();DB::transaction(function()use($id,$x,$d,$up,$r){DB::table('service_requests')->where('id',$id)->update($up);foreach(['status','assigned_to','priority'] as $k)if((string)$x->$k!==(string)($d[$k]??null))DB::table('service_request_events')->insert(['service_request_id'=>$id,'user_id'=>$r->user()->id,'event'=>$k.'_changed','from_value'=>$x->$k,'to_value'=>$d[$k]??null,'created_at'=>now(),'updated_at'=>now()]);});return back();}
public function rate(Request $r,$id){$x=DB::table('service_requests')->find($id);abort_if(!$x,404);abort_unless($x->created_by===$r->user()->id&&in_array($x->status,['resolved','closed']),403);$d=$r->validate(['rating'=>'required|integer|min:1|max:5','rating_comment'=>'nullable|string|max:3000']);DB::table('service_requests')->where('id',$id)->update($d+['updated_at'=>now()]);return back();}
public function file(Request $r,$file){$f=DB::table('service_request_files')->find($file);abort_if(!$f,404);$x=DB::table('service_requests')->find($f->service_request_id);abort_unless($x&&$this->canSee($r,$x),403);abort_unless(Storage::disk('local')->exists($f->path),404);return Storage::disk('local')->download($f->path,$f->original_name);}
public function edo(Request $r,$id,DocumentIntegrationService $docs){$x=DB::table('service_requests')->find($id);abort_if(!$x,404);abort_unless($this->staff($r)||$x->created_by===$r->user()->id,403);$p=$r->attributes->get('academic_period');$snap=['request'=>$x,'messages'=>DB::table('service_request_messages')->where(['service_request_id'=>$id,'internal'=>0])->get()];$doc=$docs->create($r->user(),$p->id,'requests','service_request',$id,'appeal','Обращение '.$x->number.': '.$x->title,$snap,['body'=>$x->description]);return redirect()->route('edo.show',$doc);}
}